('088d874c-a61e-5b58-a7a9-497f32a56901', '27afde91-58fd-5daa-b9fa-7f93f00135f0', 'a0000001-0000-0000-0000-000000000004', 'Mô tô nước – Danabeach', 'Jetski Experience – Danabeach', 'mo-to-nuoc-danabeach', 'Trải nghiệm điều khiển mô tô nước trên biển theo hướng dẫn của đơn vị tổ chức. Giá và thời lượng hiện có hai mô tả nguồn cần đối chiếu.', 'Ocean jetski riding experience with instructor briefing. Price and duration currently reference two source descriptions requiring verification.', '650000.00', 15, NULL, '51 Võ Nguyên Giáp, Đà Nẵng', '51 Võ Nguyên Giáp, Đà Nẵng', NULL, NULL, TRUE, 19.44, 1.2, '0.00', 0, 0, 'PUBLISHED', NULL, 'Người tham gia bắt buộc mặc áo phao có còi cứu sinh, chỉ điều khiển trong vùng phao tiêu an toàn quy định và tuân thủ hướng dẫn viên.', 'Participants must wear certified life jackets with whistle, operate only within designated safety buoy zones, and strictly obey instructor guidance.', TRUE, 1, NOW(), NOW()),
('160e67fc-f236-5871-9971-5555cf855d02', '5a53c8e5-3a76-5383-b104-17b22d4af50f', '762dff4f-cdd4-49fd-8e19-a9c99c2752de', 'Thuê ván SUP – Surf Shack', 'SUP Board Rental – Surf Shack', 'thue-van-sup-surf-shack', 'Thuê ván SUP theo dòng giá riêng trên website Surf Shack. Giữ riêng với thuê ván lướt sóng vì là nhóm thiết bị và trải nghiệm khác.', 'SUP board rental with dedicated pricing from Surf Shack website. Maintained separately from surfboard rental as distinct equipment and activity.', '140000.00', 60, NULL, 'Surf Shack beach house; địa chỉ bãi cụ thể cần xác nhận', NULL, NULL, NULL, TRUE, 18.0, 0.8, NULL, 0, 0, 'PUBLISHED', NULL, 'Học viên cam kết biết bơi cơ bản, luôn gắn dây buộc chân an toàn vào ván và tuân thủ khu vực thực hành theo chỉ dẫn của huấn luyện viên.', 'Students confirm basic swimming ability, must keep the safety leash attached to the surfboard at all times, and practice only within designated safe zones.', TRUE, 1, NOW(), NOW()),
('1dd26db5-f863-5b03-b562-ac46f43df9d2', '631db4cf-1ec4-5b06-8f98-56abcf3406d0', 'b6d82a0f-ebbd-4d26-8363-17599c90e058', 'Lớp học lướt sóng Mỹ Khê – DNOA', 'My Khe Surfing Lesson – DNOA', 'lop-hoc-luot-song-my-khe-dnoa', 'Lớp học lướt sóng gồm hướng dẫn kỹ thuật trên bờ và thực hành trên biển theo trang DNOA. Các cấu hình nhóm nằm trong một Service, chưa áp dụng giá tuyến tính cho mọi số khách.', 'Surfing lessons featuring beach safety briefings and in-water practice per DNOA. Group configurations are within one Service without linear pricing.', '1100000.00', 120, NULL, 'Bãi biển Mỹ Khê, Đà Nẵng', NULL, NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Học viên cam kết biết bơi cơ bản, luôn gắn dây buộc chân an toàn vào ván và tuân thủ khu vực thực hành theo chỉ dẫn của huấn luyện viên.', 'Students confirm basic swimming ability, must keep the safety leash attached to the surfboard at all times, and practice only within designated safe zones.', TRUE, 1, NOW(), NOW()),
('2cdfabcf-13a2-550a-8f9e-283aad7053c9', 'baea9605-392b-5003-93f1-60f2c0582f65', 'a0000001-0000-0000-0000-000000000004', 'Mô tô nước – Kajin Vina', 'Jetski Experience – Kajin Vina', 'mo-to-nuoc-kajin-vina', 'Trải nghiệm mô tô nước tại khu vực biển theo hồ sơ khảo sát. Ảnh được dùng minh họa hoạt động, không xác nhận đây là xe hoặc khách của Kajin.', 'Ocean jetski riding per survey dossier. Images are for activity illustration only and do not certify actual Kajin vehicles or customers.', '650000.00', 15, NULL, 'Bãi biển Mỹ Khê, Đà Nẵng', 'Bãi biển Mỹ Khê, Đà Nẵng', NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Người tham gia bắt buộc mặc áo phao có còi cứu sinh, chỉ điều khiển trong vùng phao tiêu an toàn quy định và tuân thủ hướng dẫn viên.', 'Participants must wear certified life jackets with whistle, operate only within designated safety buoy zones, and strictly obey instructor guidance.', TRUE, 1, NOW(), NOW()),
('3758c297-54ff-5887-89bd-62220227570b', '27afde91-58fd-5daa-b9fa-7f93f00135f0', 'a0000001-0000-0000-0000-000000000003', 'Dù bay trên biển – Danabeach', 'Ocean Parasailing – Danabeach', 'du-bay-tren-bien-danabeach', 'Trải nghiệm dù bay trên biển với lựa chọn bay đơn hoặc bay đôi. Cách tính giá trong khảo sát và bài tham chiếu chưa thống nhất.', 'Coastal parasailing experience with single or tandem flight options. Pricing calculations in the survey and reference articles require alignment.', '650000.00', 15, NULL, '51 Võ Nguyên Giáp, Đà Nẵng', '51 Võ Nguyên Giáp, Đà Nẵng', NULL, NULL, TRUE, 18.0, 0.8, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đảm bảo điều kiện sức khỏe, không có tiền sử bệnh tim mạch hoặc sợ độ cao. Bắt buộc mặc áo phao chuyên dụng và cài đai an toàn theo hướng dẫn của kỹ thuật viên.', 'Participants confirm they are in good health with no history of cardiovascular issues or severe acrophobia. Wearing a certified life jacket and harness as instructed by safety staff is mandatory.', TRUE, 1, NOW(), NOW()),
('4190046d-112a-5b93-beb2-bcc8b1cd16d4', 'baea9605-392b-5003-93f1-60f2c0582f65', 'a0000001-0000-0000-0000-000000000003', 'Dù bay trên biển – Kajin Vina', 'Ocean Parasailing – Kajin Vina', 'du-bay-tren-bien-kajin-vina', 'Trải nghiệm dù bay theo lựa chọn đơn hoặc đôi trong hồ sơ khảo sát. Bãi hoạt động cần được xác nhận riêng với địa chỉ văn phòng.', 'Parasailing flight with single or tandem options per survey dossier. Operating beach location must be confirmed independently from office address.', '650000.00', 15, NULL, 'Khu vực biển Đà Nẵng (điểm hẹn cần Vendor xác nhận)', NULL, NULL, NULL, TRUE, 18.0, 0.8, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đảm bảo điều kiện sức khỏe, không có tiền sử bệnh tim mạch hoặc sợ độ cao. Bắt buộc mặc áo phao chuyên dụng và cài đai an toàn theo hướng dẫn của kỹ thuật viên.', 'Participants confirm they are in good health with no history of cardiovascular issues or severe acrophobia. Wearing a certified life jacket and harness as instructed by safety staff is mandatory.', TRUE, 1, NOW(), NOW()),
('4b79c4cd-a138-59ca-83c3-d396c1208ac4', '5a53c8e5-3a76-5383-b104-17b22d4af50f', 'c00581cc-26dd-4dc2-a87d-2590f76943f3', 'Thuê ván lướt sóng – Surf Shack', 'Surfboard Rental – Surf Shack', 'thue-van-luot-song-surf-shack', 'Thuê ván lướt sóng theo loại ván và kỳ thuê được công bố trên trang Surf Shack. Ba loại ván được giữ dưới dạng Option trong một Service.', 'Surfboard rental by board type and duration published on Surf Shack site. Three board types are structured as Options within a single Service.', '110000.00', 60, NULL, 'Surf Shack / beach house Mỹ Khê, Đà Nẵng', NULL, NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Học viên cam kết biết bơi cơ bản, luôn gắn dây buộc chân an toàn vào ván và tuân thủ khu vực thực hành theo chỉ dẫn của huấn luyện viên.', 'Students confirm basic swimming ability, must keep the safety leash attached to the surfboard at all times, and practice only within designated safe zones.', TRUE, 1, NOW(), NOW()),
('508d4dad-4227-527b-9df3-8416dd870c04', '631db4cf-1ec4-5b06-8f98-56abcf3406d0', 'c00581cc-26dd-4dc2-a87d-2590f76943f3', 'Thuê ván lướt sóng – DNOA', 'Surfboard Rental – DNOA', 'thue-van-luot-song-dnoa', 'Thuê ván lướt sóng theo sản phẩm foamie được công bố trên website DNOA. Các kỳ thuê Half Day và Full Day được giữ là lựa chọn, không tạo thêm Service.', 'Soft-top foamie surfboard rental as listed on DNOA website. Half Day and Full Day rental terms are retained as Options within one Service.', '120000.00', 60, NULL, 'Bãi biển Mỹ Khê, Đà Nẵng', NULL, NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Học viên cam kết biết bơi cơ bản, luôn gắn dây buộc chân an toàn vào ván và tuân thủ khu vực thực hành theo chỉ dẫn của huấn luyện viên.', 'Students confirm basic swimming ability, must keep the safety leash attached to the surfboard at all times, and practice only within designated safe zones.', TRUE, 1, NOW(), NOW()),
('5536f743-3b6d-518e-af2b-05634a218195', '5fb18fee-16fd-5b9f-bcbd-759b47768d9b', '0647f498-72e0-46ba-9192-a833e238e41e', 'Câu cá chuyên nghiệp Sơn Trà – DaNaFi', 'Pro Sea Fishing Son Tra – DaNaFi', 'cau-ca-chuyen-nghiep-son-tra-danafi', 'Chương trình câu cá biển với các kỹ thuật câu được giới thiệu trên trang DaNaFi, có hướng dẫn và bữa ăn theo nguồn. Giữ riêng với gói câu cá trải nghiệm ngắn hơn.', 'Ocean fishing program covering specialized techniques per DaNaFi, including guide and meals. Distinct from shorter recreational fishing tours.', '750000.00', 450, NULL, 'Vùng biển bán đảo Sơn Trà, Đà Nẵng', NULL, NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đủ sức khỏe tham gia, bắt buộc mặc áo phao trong suốt hành trình và tuân thủ nghiêm ngặt chỉ dẫn của hướng dẫn viên cứu hộ.', 'Participants confirm good health condition, must wear life jackets throughout the trip, and strictly follow rescue guide instructions.', TRUE, 1, NOW(), NOW()),
('57c22a43-22fd-57da-894c-257ade02450d', '10f8ffc5-e987-592f-9d38-426ad7f97066', 'a0000001-0000-0000-0000-000000000002', 'Lặn ngắm san hô Sơn Trà – Loca Travel', 'Son Tra Coral Snorkeling – Loca Travel', 'lan-ngam-san-ho-son-tra-loca-travel', 'Trải nghiệm ngắm san hô tại Sơn Trà, trình bày tham khảo theo nguồn Loca hiện mô tả Bãi Rạng. Hồ sơ khảo sát Bãi Cát Vàng vẫn được lưu riêng; chưa xác nhận hai gói tương đương thương mại.', 'Son Tra coral snorkeling referencing Loca source describing Bai Rang. Bai Cat Vang survey dossier kept separate; commercial parity unconfirmed.', '450000.00', 240, NULL, 'Khu Du Lịch Bãi Cát Vàng, Bán Đảo Sơn Trà', 'Bãi Cát Vàng, Phía Bắc Bán Đảo Sơn Trà, Đà Nẵng', NULL, NULL, TRUE, 18.7, 1.0, NULL, 0, 0, 'PUBLISHED', NULL, 'Khách hàng xác nhận không có tiền sử bệnh tim mạch, huyết áp hoặc hen suyễn; bắt buộc mặc áo phao hoặc thiết bị lặn chuyên dụng và tuân thủ quy chuẩn an toàn biển.', 'Participants confirm no history of cardiovascular, blood pressure, or asthma conditions. Wearing life vests or specialized diving gear and adhering to marine safety protocols is mandatory.', TRUE, 1, NOW(), NOW()),
('5943ecd7-6480-5b4a-b42b-43abc0988776', '5a53c8e5-3a76-5383-b104-17b22d4af50f', 'b6d82a0f-ebbd-4d26-8363-17599c90e058', 'Học lướt sóng – Surf Shack', 'Surfing Lessons – Surf Shack', 'hoc-luot-song-surf-shack', 'Học kỹ năng lướt sóng với hướng dẫn trên bờ và thực hành trên biển theo nguồn Surf Shack. Thời lượng và giá lớp hiện có nhiều cấu hình cần xác nhận.', 'Surfing skills instruction with beach theory and ocean practice per Surf Shack. Lesson duration and pricing have multiple configs needing review.', '800000.00', 120, NULL, 'Bãi Biển Mỹ Khê', 'Đường Võ Nguyên Giáp, Phước Mỹ, Sơn Trà, Đà Nẵng', NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Học viên cam kết biết bơi cơ bản, luôn gắn dây buộc chân an toàn vào ván và tuân thủ khu vực thực hành theo chỉ dẫn của huấn luyện viên.', 'Students confirm basic swimming ability, must keep the safety leash attached to the surfboard at all times, and practice only within designated safe zones.', TRUE, 1, NOW(), NOW()),
('6d4249fe-a82b-5537-a712-818b23c177d2', '631db4cf-1ec4-5b06-8f98-56abcf3406d0', 'a0000001-0000-0000-0000-000000000001', 'Kayak kết hợp trải nghiệm biển – DNOA', 'Kayak & Ocean Experience – DNOA', 'kayak-ket-hop-trai-nghiem-bien-dnoa', 'Chèo kayak theo hướng dẫn, kết hợp trải nghiệm biển như hồ sơ nguồn. Mô tả khảo sát và sản phẩm kayak–snorkel hiện trên website khác nhau, cần xác định đúng gói.', 'Guided kayak paddling combined with ocean exploration per source records. Survey description and current website kayak-snorkel package differ.', '850000.00', 120, NULL, 'Bãi Rạng - Bán đảo Sơn Trà, Đà Nẵng', 'Bãi Rạng, Đường Hoàng Sa, Phường Thọ Quang, Sơn Trà, Đà Nẵng', NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đủ sức khỏe tham gia, bắt buộc mặc áo phao trong suốt hành trình và tuân thủ nghiêm ngặt chỉ dẫn của hướng dẫn viên cứu hộ.', 'Participants confirm good health condition, must wear life jackets throughout the trip, and strictly follow rescue guide instructions.', TRUE, 1, NOW(), NOW()),
('83ee83c5-c08b-5f6e-924e-db3ceaacd364', '27afde91-58fd-5daa-b9fa-7f93f00135f0', 'a0000001-0000-0000-0000-000000000005', 'Phao chuối – Danabeach', 'Banana Boat Ride – Danabeach', 'phao-chuoi-danabeach', 'Trải nghiệm phao chuối được kéo trên mặt nước biển cùng nhóm. Hồ sơ khảo sát ghi có áo phao và hướng dẫn trước hoạt động.', 'Group banana boat ride towed across ocean waters. Survey record notes life jacket provision and pre-activity safety briefing.', '1000000.00', 10, NULL, '51 Võ Nguyên Giáp, Đà Nẵng', '51 Võ Nguyên Giáp, Đà Nẵng', NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đủ sức khỏe tham gia, bắt buộc mặc áo phao trong suốt hành trình và tuân thủ nghiêm ngặt chỉ dẫn của hướng dẫn viên cứu hộ.', 'Participants confirm good health condition, must wear life jackets throughout the trip, and strictly follow rescue guide instructions.', TRUE, 1, NOW(), NOW()),
('88e06f4d-fbb7-5700-a45d-0f6ad1cb0d08', '128672c5-94e7-5560-896c-158794913b8c', '0647f498-72e0-46ba-9192-a833e238e41e', 'Câu cá biển bằng cano riêng – D2Tour', 'Private Speedboat Fishing – D2Tour', 'cau-ca-bien-bang-cano-rieng-d2tour', 'Chuyến câu cá biển bằng cano riêng theo hồ sơ khảo sát. Tuyến biển có thể đi qua khu vực Sơn Trà–Cù Lao Chàm để câu cá; đây không phải tour đảo tham quan tổng hợp.', 'Private speedboat ocean fishing charter per survey records. Route may cover Son Tra–Cu Lao Cham for fishing; not a generic sightseeing island tour.', '2400000.00', 240, NULL, 'Vùng Biển Sơn Trà – Cù Lao Chàm', 'Khởi hành từ Bến thuyền Thọ Quang, Đà Nẵng', NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đủ sức khỏe tham gia, bắt buộc mặc áo phao trong suốt hành trình và tuân thủ nghiêm ngặt chỉ dẫn của hướng dẫn viên cứu hộ.', 'Participants confirm good health condition, must wear life jackets throughout the trip, and strictly follow rescue guide instructions.', TRUE, 1, NOW(), NOW()),
('9b3444ce-b7c7-5f40-9f14-2c1ca4258dea', '2680f19f-8b5a-5aa8-8474-cb13e2ff1c22', '52ced236-bce3-4044-9a4f-ca3559e24cfb', 'Câu mực đêm – Khuê Nguyễn', 'Night Squid Fishing – Khue Nguyen', 'cau-muc-dem-khue-nguyen', 'Trải nghiệm câu mực vào buổi tối trên thuyền theo hồ sơ khảo sát. Các khung giờ tối và qua đêm được giữ riêng để đối chiếu thời lượng và khả năng tổ chức.', 'Evening boat squid fishing experience per survey dossier. Evening and overnight departures are separated to track durations and operations.', '350000.00', 300, NULL, 'Vùng Biển Thọ Quang – Sơn Trà', 'Cảng cá Thọ Quang, phường Thọ Quang, Sơn Trà, Đà Nẵng', NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đủ sức khỏe tham gia, bắt buộc mặc áo phao trong suốt hành trình và tuân thủ nghiêm ngặt chỉ dẫn của hướng dẫn viên cứu hộ.', 'Participants confirm good health condition, must wear life jackets throughout the trip, and strictly follow rescue guide instructions.', TRUE, 1, NOW(), NOW()),
('9b575c51-196b-56eb-940e-aaf2f61c966f', '631db4cf-1ec4-5b06-8f98-56abcf3406d0', 'a0000001-0000-0000-0000-000000000001', 'Học kayak và trò chơi Splash & Dash – DNOA', 'Kayak Lessons & Splash and Dash – DNOA', 'hoc-kayak-va-tro-choi-splash-dash-dnoa', 'Trải nghiệm học chèo kayak kết hợp trò chơi trên nước theo trang DNOA. Gói không được mô tả như tour snorkeling; địa điểm và lịch chi tiết cần đối chiếu.', 'Kayak paddling instruction paired with water games per DNOA. Package is not framed as a snorkeling tour; exact location and schedule need review.', '550000.00', 90, NULL, 'Khu vực biển Mỹ Khê, Đà Nẵng (điểm hẹn cần Vendor xác nhận)', NULL, NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đủ sức khỏe tham gia, bắt buộc mặc áo phao trong suốt hành trình và tuân thủ nghiêm ngặt chỉ dẫn của hướng dẫn viên cứu hộ.', 'Participants confirm good health condition, must wear life jackets throughout the trip, and strictly follow rescue guide instructions.', TRUE, 1, NOW(), NOW()),
('9f4eb04d-9ec6-5295-8de6-475b728e5cfc', '5a53c8e5-3a76-5383-b104-17b22d4af50f', 'bab1c632-d82a-452a-8230-2028a67fac31', 'Surf tour tìm điểm sóng – Surf Shack', 'Surf Spot Guiding Tour – Surf Shack', 'surf-tour-tim-diem-song-surf-shack', 'Trải nghiệm lướt sóng có hướng dẫn tìm điểm sóng phù hợp quanh Sơn Trà–Hội An. Chương trình dành cho khách đã có khả năng bắt sóng, không phải tour tham quan tổng hợp.', 'Guided surf trip tracking suitable breaks around Son Tra–Hoi An. Designed for surfers with wave-catching ability, not a sightseeing tour.', '400000.00', 150, NULL, 'Tuyến điểm sóng Sơn Trà – Hội An', NULL, NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Học viên cam kết biết bơi cơ bản, luôn gắn dây buộc chân an toàn vào ván và tuân thủ khu vực thực hành theo chỉ dẫn của huấn luyện viên.', 'Students confirm basic swimming ability, must keep the safety leash attached to the surfboard at all times, and practice only within designated safe zones.', TRUE, 1, NOW(), NOW()),
('a6f4ab9c-4794-542b-a443-e3013e6bbe47', '5fb18fee-16fd-5b9f-bcbd-759b47768d9b', '0647f498-72e0-46ba-9192-a833e238e41e', 'Câu cá biển Sơn Trà – DaNaFi', 'Son Tra Sea Fishing – DaNaFi', 'cau-ca-bien-son-tra-danafi', 'Trải nghiệm câu cá trên biển Sơn Trà theo hồ sơ khảo sát, có dụng cụ và hướng dẫn. Giữ riêng gói này với chương trình câu cá chuyên nghiệp của cùng Vendor.', 'Recreational Son Tra ocean fishing per survey dossier, with tackle and guide. Kept distinct from pro fishing packages by the same Vendor.', '650000.00', 240, NULL, 'Rạn San Hô Bán Đảo Sơn Trà', 'Vùng biển bán đảo Sơn Trà, Sơn Trà, Đà Nẵng', NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đủ sức khỏe tham gia, bắt buộc mặc áo phao trong suốt hành trình và tuân thủ nghiêm ngặt chỉ dẫn của hướng dẫn viên cứu hộ.', 'Participants confirm good health condition, must wear life jackets throughout the trip, and strictly follow rescue guide instructions.', TRUE, 1, NOW(), NOW()),
('bf8626cd-2271-59ab-9273-4fdd10eb451e', '631db4cf-1ec4-5b06-8f98-56abcf3406d0', 'fe49b1a1-6c7f-4eb0-a08f-0d65c02c36d5', 'Thuê kayak đơn hoặc đôi – DNOA', 'Single & Double Kayak Rental – DNOA', 'thue-kayak-don-hoac-doi-dnoa', 'Thuê kayak đơn hoặc đôi theo danh mục cho thuê của DNOA. Đây là thuê thiết bị, tách khỏi lớp học kayak và chương trình kayak–snorkel.', 'Single or tandem kayak rentals from DNOA inventory. Strictly gear hire, separated from kayak instruction and kayak-snorkel excursions.', '150000.00', 60, NULL, 'Bãi biển Mỹ Khê, Đà Nẵng', NULL, NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đủ sức khỏe tham gia, bắt buộc mặc áo phao trong suốt hành trình và tuân thủ nghiêm ngặt chỉ dẫn của hướng dẫn viên cứu hộ.', 'Participants confirm good health condition, must wear life jackets throughout the trip, and strictly follow rescue guide instructions.', TRUE, 1, NOW(), NOW()),
('c4c56ae2-5f9b-555c-81f1-f0d4c8dd7c1b', '631db4cf-1ec4-5b06-8f98-56abcf3406d0', 'a0000001-0000-0000-0000-000000000003', 'Dù bay trên biển – DNOA', 'Ocean Parasailing – DNOA', 'du-bay-tren-bien-dnoa', 'Bay dù được kéo bằng phương tiện trên biển tại Mỹ Khê. Nguồn DNOA có lựa chọn bay đơn hoặc bay đôi, cùng hướng dẫn và trang bị cho hoạt động.', 'Speedboat-towed parasailing flight at My Khe. DNOA source offers single or tandem flights, safety gear, and operational instruction.', '650000.00', 15, NULL, 'Mỹ Khê; điểm hẹn cạnh Beach Bar Da Nang', 'Mỹ Khê; điểm hẹn cạnh Beach Bar Da Nang', NULL, NULL, TRUE, 18.0, 0.8, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đảm bảo điều kiện sức khỏe, không có tiền sử bệnh tim mạch hoặc sợ độ cao. Bắt buộc mặc áo phao chuyên dụng và cài đai an toàn theo hướng dẫn của kỹ thuật viên.', 'Participants confirm they are in good health with no history of cardiovascular issues or severe acrophobia. Wearing a certified life jacket and harness as instructed by safety staff is mandatory.', TRUE, 1, NOW(), NOW()),
('cd0c7a8d-b0b8-579a-968c-a1783174a0fc', 'c7dcff25-f5dc-5fee-a719-5c23b6a899cb', 'a0000001-0000-0000-0000-000000000001', 'Chèo SUP Mân Thái – Go N Chill', 'Man Thai SUP Paddling – Go N Chill', 'cheo-sup-man-thai-go-n-chill', 'Trải nghiệm chèo SUP tại khu vực Mân Thái theo khảo sát và website Go N Chill. Giá, dịch vụ kèm theo và thời lượng cần đối chiếu trước khi bán.', 'SUP paddling at Man Thai beach per survey and Go N Chill site. Pricing, bundled services, and duration require review before commercial launch.', '150000.00', 135, 30, 'Bãi tắm Mân Thái, Đà Nẵng', 'Đường Hoàng Sa, Phường Mân Thái, Quận Sơn Trà, Đà Nẵng', NULL, NULL, TRUE, 18.0, 0.8, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đủ sức khỏe tham gia, bắt buộc mặc áo phao trong suốt hành trình và tuân thủ nghiêm ngặt chỉ dẫn của hướng dẫn viên cứu hộ.', 'Participants confirm good health condition, must wear life jackets throughout the trip, and strictly follow rescue guide instructions.', TRUE, 1, NOW(), NOW()),
('d51355fc-bf7e-5366-b199-6272efe7f52b', '10f8ffc5-e987-592f-9d38-426ad7f97066', 'a0000001-0000-0000-0000-000000000002', 'Lặn ngắm san hô Bãi Nam – Loca Travel', 'Bai Nam Coral Snorkeling – Loca Travel', 'lan-ngam-san-ho-bai-nam-loca-travel', 'Trải nghiệm quan sát san hô và sinh vật biển bằng mặt nạ, ống thở tại khu vực Bãi Nam theo khảo sát. Gói có vận chuyển cano và hướng dẫn trong hồ sơ nguồn.', 'Coral and marine life snorkeling experience at Bai Nam per survey. Includes speedboat transfers and guide per original source records.', '350000.00', 150, NULL, 'Bãi Nam - Bán Đảo Sơn Trà, Đà Nẵng', 'Bãi Nam, Đường Hoàng Sa, Phường Thọ Quang, Sơn Trà, Đà Nẵng', NULL, NULL, TRUE, 18.7, 1.0, NULL, 0, 0, 'PUBLISHED', NULL, 'Khách hàng xác nhận không có tiền sử bệnh tim mạch, huyết áp hoặc hen suyễn; bắt buộc mặc áo phao hoặc thiết bị lặn chuyên dụng và tuân thủ quy chuẩn an toàn biển.', 'Participants confirm no history of cardiovascular, blood pressure, or asthma conditions. Wearing life vests or specialized diving gear and adhering to marine safety protocols is mandatory.', TRUE, 1, NOW(), NOW()),
('dab42f5f-e61d-5ebf-811d-34ab8d293143', '5fb18fee-16fd-5b9f-bcbd-759b47768d9b', '52ced236-bce3-4044-9a4f-ca3559e24cfb', 'Câu mực đêm có bữa tối – DaNaFi', 'Night Squid Fishing with Dinner – DaNaFi', 'cau-muc-dem-co-bua-toi-danafi', 'Chương trình câu mực đêm trên biển Sơn Trà được mô tả trong nội dung chỉ mục của nguồn DaNaFi. Bữa tối và chương trình cần xác nhận trực tiếp vì trang chi tiết chưa mở được.', 'Son Tra night squid fishing tour described in DaNaFi indexed pages. Dinner and itinerary require confirmation as detail page was unreachable.', '550000.00', 210, NULL, 'Vùng biển bán đảo Sơn Trà, Đà Nẵng', NULL, NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đủ sức khỏe tham gia, bắt buộc mặc áo phao trong suốt hành trình và tuân thủ nghiêm ngặt chỉ dẫn của hướng dẫn viên cứu hộ.', 'Participants confirm good health condition, must wear life jackets throughout the trip, and strictly follow rescue guide instructions.', TRUE, 1, NOW(), NOW()),
('fd6fced2-812e-56ce-817f-80bb3d0841e9', 'baea9605-392b-5003-93f1-60f2c0582f65', 'a0000001-0000-0000-0000-000000000005', 'Phao chuối – Kajin Vina', 'Banana Boat Ride – Kajin Vina', 'phao-chuoi-kajin-vina', 'Hoạt động phao chuối kéo trên biển dành cho nhóm khách. Địa chỉ văn phòng trong hồ sơ không được dùng thay cho bãi trải nghiệm.', 'Speedboat-towed banana boat activity for groups. Office address in survey records is not substituted for the actual beach departure point.', '1000000.00', 12, NULL, 'Khu vực biển Đà Nẵng (điểm hẹn cần Vendor xác nhận)', NULL, NULL, NULL, TRUE, 19.44, 1.2, NULL, 0, 0, 'PUBLISHED', NULL, 'Du khách cam kết đủ sức khỏe tham gia, bắt buộc mặc áo phao trong suốt hành trình và tuân thủ nghiêm ngặt chỉ dẫn của hướng dẫn viên cứu hộ.', 'Participants confirm good health condition, must wear life jackets throughout the trip, and strictly follow rescue guide instructions.', TRUE, 1, NOW(), NOW())
